:local today [/system clock get date]
:local authToken "mcwifi_secret_token_2026"
:local count 0
:foreach s in=[/system script find where source=$today] do={
  :local sName [/system script get $s name]
  :if ([:pick $sName 0 4] = "2026") do={
    :set count ($count + 1)
    :do {
      /tool fetch url=("https://2mc.alwaysdata.net/api/router/record-script?token=" . $authToken . "&name=" . $sName) keep-result=no
    } on-error={}
  }
}
:log info ("AlwaysDataSyncRecent: Synced " . $count . " scripts for date " . $today)
